style.css:
/* NIGHTSHIFT — Obsidian Minimal */
/* i really want this to be global */

/* swap these values to change the look */
:root {
  --my-bg: #050607;
  --my-surface: #0a0c0e;
  --my-surface-raised: #0e1114;
  --my-border: #252b30;
  --my-border-strong: #39434b;
  --my-text: #e1e6e9;
  --my-muted: #78838c;
  --my-accent: #a9c2d0;
  --my-radius: 3px;
}

/* dark foundations */
html,
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
  color-scheme: dark !important;
}

/* clean typography */
body {
  font-family: "Inter", "SF Pro Display", "Segoe UI", sans-serif !important;
  letter-spacing: 0.015em !important;
}

/* outlined surfaces */
header,
nav,
main,
aside,
section,
article,
footer,
[role="dialog"],
[role="menu"],
input,
textarea,
select,
button {
  border-color: var(--my-border) !important;
}

/* subtle technical surfaces */
input,
textarea,
select,
button {
  background-color: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border-strong) !important;
  border-radius: var(--my-radius) !important;
  box-shadow: none !important;
}

/* crisp interactive states */
button:hover,
input:focus,
textarea:focus,
select:focus {
  border-color: var(--my-accent) !important;
  outline: 1px solid var(--my-accent) !important;
  outline-offset: 2px !important;
}

/* understated links */
a {
  color: var(--my-accent) !important;
  text-decoration-color: var(--my-border-strong) !important;
  text-underline-offset: 3px !important;
}

/* clean image treatment */
img,
video,
picture {
  border-radius: 2px !important;
}

/* remove excessive shadows */
* {
  text-shadow: none !important;
  box-shadow: none !important;
}

/* quiet scrollbars */
* {
  scrollbar-color: #303941 #080a0c !important;
  scrollbar-width: thin !important;
}

/* restrained selection */
::selection {
  background: #344956 !important;
  color: #ffffff !important;
}
